arguments.command:
python -c "
# More Python format string tests
cases = [
    '{a}',        # valid field
    '{{a}}',      # escaped {a}
    '{{{a}}}',    # escaped {{ + field a + }}
    'hello {world}',  # text + field
    '{{ hello }}',  # escaped braces around text
]

for s in cases:
    try:
        result = s.format()
        print(f'{repr(s):20} -> {repr(result)}')
    except Exception as e:
        print(f'{repr(s):20} -> ERROR: {type(e).__name__}')
" 2>&1
